ValidationRule.errorConditionFormula:
AND(
  ISCHANGED( Separate_Project__c ) ,
  Separate_Project__c ,
  NOT(
    OR(
      ISPICKVAL( SBQQ__BillingFrequency__c , "Invoice Plan" ) ,
      AND(
        ISPICKVAL( SBQQ__BillingType__c , "Arrears" ) ,
        ISPICKVAL( SBQQ__BillingFrequency__c , "Monthly" )
      )
    )
  )
)
